urrency?' '+e.currency:''));if(e.allotment!==undefined&&e.allotment!==null)parts.push('kontenjan: '+e.allotment);if(e.stop_sale!==undefined)parts.push('satış kapalı: '+(e.stop_sale?'evet':'hayır'));if(e.min_stay!==undefined)parts.push('min konaklama: '+e.min_stay);if(e.max_stay!==undefined&&e.max_stay!==null)parts.push('max konaklama: '+e.max_stay);if(d.summary)parts.push(d.summary.applied_rows+' uygulandı · '+d.summary.skipped_rows+' atlandı (son '+d.summary.logs_seen+' işlem)');if(d.fx_audit&&d.fx_audit.length){var fx=d.fx_audit.map(function(f){return f.from+'→'+f.to+' · kur '+f.rate+(f.count>1?' · '+f.count+' fiyat':'')+' · '+f.original_total+' '+f.from+' → '+f.converted_total+' '+f.to;});parts.push('dönüşüm: '+fx.join('; '));}res.textContent=parts.join(' · ');res.className='room-verify-result'+(d.log.status==='failed'?' err':'');if(d.log.status==='failed'){var a=document.createElement('a');a.href='#sync-log-'+(d.log.id||0);a.className='verify-log-jump';a.textContent=' İşlem günlüğünde gör →';a.addEventListener('click',function(e){e.preventDefault();var r=document.getElementById('sync-log-'+(d.log.id||0));if(r){r.scrollIntoView({behavior:'smooth',block:'center'});r.classList.add('log-row-flash');setTimeout(function(){r.classList.remove('log-row-flash')},2200)}});res.appendChild(a);}res.hidden=false}).catch(function(){btn.textContent=old;btn.disabled=false;delete btn.dataset.loading;res.textContent='Doğrulama yapılamadı (ağ/oturum).';res.className='room-verify-result err';res.hidden=false})})});document.querySelectorAll('.room-test-btn').forEach(function(b){b.addEventListener('click',function(){var btn=this,row=btn.closest('[data-verify-box]');if(!row)return;var res=row.querySelector('.room-verify-result');if(btn.dataset.loading)return;var sel=row.querySelector('.room-test-currency');var cur=sel?sel.value:'';btn.dataset.loading='1';var old=btn.textContent;btn.textContent='…';btn.disabled=true;fetch('/nexustraveltech/api/supplier-room-test.php?connection_id='+encodeURIComponent(btn.dataset.conn)+'&property_id='+encodeURIComponent(btn.dataset.prop)+'&code='+encodeURIComponent(btn.dataset.code)+(cur?'&currency='+encodeURIComponent(cur):''),{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(d){btn.textContent=old;btn.disabled=false;delete btn.dataset.loading;if(!d.ok){res.textContent=d.message||'Hata';res.className='room-verify-result err';res.hidden=false;return}res.textContent=d.message||'';res.className='room-verify-result'+(d.ready?' ok':' err');res.hidden=false}).catch(function(){btn.textContent=old;btn.disabled=false;delete btn.dataset.loading;res.textContent='Test yapılamadı (ağ/oturum).';res.className='room-verify-result err';res.hidden=false})})});(function(){if(!location.hash||location.hash.indexOf('#channel-retry')!==0)return;var target=null;if(location.hash.length>14){target=document.getElementById(location.hash.slice(1))}if(!target){target=document.querySelector('form[data-channel-retry]')}if(target){setTimeout(function(){var y=target.getBoundingClientRect().top+window.scrollY-110;window.scrollTo({top:y,behavior:'smooth'});var btn=target.querySelector('button');if(btn){btn.focus({preventScroll:true});btn.classList.add('conn-retry-flash');setTimeout(function(){btn.classList.remove('conn-retry-flash')},2200)}},80)}})();document.querySelectorAll('.conn-code-chip').forEach(function(ch){ch.addEventListener('click',function(){var res=document.getElementById('conn-verify-'+ch.dataset.conn);if(!res)return;var prop=ch.dataset.prop||'0';if(parseInt(prop,10)<=0){res.textContent='Bu kodun ait olduğu ürün bilinmiyor — ⚡ ikonuyla ürün seçip hızlı eşleştirme yapın, sonra Doğrula ile kontrol edin.';res.className='room-verify-result';res.hidden=false;return;}roomVerifyShow(res,ch.dataset.conn,prop,ch.dataset.code);})});
document.querySelectorAll('.chip-action[data-act="flow"]').forEach(function(b){b.addEventListener('click',function(){var wrap=b.parentNode;var ch=wrap?wrap.querySelector('.conn-code-chip'):null;if(!ch)return;var form=null;document.querySelectorAll('form').forEach(function(f){if(form)return;var h=f.querySelector('input[name="action"]');if(h&&h.value==='room_map_edit')form=f;});if(!form){alert('Oda eşleştirme formu bulunamadı — sayfayı yenileyin.');return;}var conn=ch.dataset.conn||'',prop=ch.dataset.prop||'0',code=ch.dataset.code||'';var cs=form.querySelector('select[name="connection_id"]'),ps=form.querySelector('select[name="property_id"]');var okConn=false;if(cs){Array.prototype.forEach.call(cs.options,function(o){if(o.value===conn){cs.value=conn;okConn=true;}});}if(ps){Array.prototype.forEach.call(ps.options,function(o){if(o.value===prop){ps.value=prop;}});}if(!okConn){alert("Bu kanal için oda eşleştirmesi bölüm 3'te düzenlenebilir.");return;}var qc=form.querySelector('input[name="quick_code"]');if(!qc){qc=document.createElement('input');qc.type='hidden';qc.name='quick_code';form.appendChild(qc);}qc.value=code;form.submit();})});var qmBtn=document.getElementById('quick-match-btn');if(qmBtn){qmBtn.addEventListener('click',function(){var sel=document.getElementById('quick-room-select');if(!sel)return;var id=parseInt(sel.value||'0',10);if(!id)return;var inp=document.getElementById('room-code-'+id);if(!inp)return;var ce=document.querySelector('.room-quick-match code');var code=ce?ce.textContent.trim():'';inp.value=code;inp.dispatchEvent(new Event('change',{bubbles:true}));inp.scrollIntoView({behavior:'smooth',block:'center'});inp.focus();inp.style.outline='2px solid #b26a00';setTimeout(function(){inp.style.outline=''},2000)})}</script><?php supply_end(); ?>
